// Install Cherow and Babylon
npm install cherow @babel/parser

// Sample JavaScript code to parse
const code = `function add(a, b) { return a + b; }`;

// Parse with Cherow
const cherow = require('cherow');
console.time('Cherow');
cherow.parse(code);
console.timeEnd('Cherow');

// Parse with Babylon
const babelParser = require('@babel/parser');
console.time('Babylon');
babelParser.parse(code, { sourceType: 'module' });
console.timeEnd('Babylon');
